-- GENERATED by `wfj generate` from data/gossip/gossip-48.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["4803b7492c692f70"] = { "Non ho tempo per le chiacchiere, qui si lavora sul serio!", "." },
  ["4808b76a34044f65"] = { "Mi dispiace, {name}, ma non ho tempo da dedicare ai novizi. Ti serve qualcuno più vicino al tuo livello. Prova con l'elfa della notte ⟦Milla Fairancora=Milla Ferancora⟧, nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus.", "." },
  ["4809cb3b24fa3321"] = { "Te lo dico io \"e poi cosa\". È corsa dritta verso l'alveare. E sai cosa c'è di ancora più folle? Nemmeno uno di quei maledetti insetti le si è messo davanti o ha provato a fermarla. È passata in mezzo a tutti quanti come se fossero amici suoi da secoli.", "." },
  ["480e4e49ab1aeae1"] = { "Maginor dice che torcere flussi alternati di energia positiva crea in realtà un flusso molto più stabile.", "." },
  ["480eaa49d30197e2"] = { "Lo ⟦The Scepter of the Shifting Sands=Scettro delle Sabbie Mutevoli⟧ è di nuovo integro, {name}.\n\nDevi essere tu a usare lo scettro. Devi essere tu ad annunciare la nuova era del tuo popolo.\n\nDevi aspettare che gli eserciti dell'⟦Horde=Orda⟧ e dell'⟦Alliance=Alleanza⟧ arrivino a ⟦Silithus=Silitus⟧ prima di poter suonare lo Scarab Gong. L'ora della guerra è vicina.", "." },
  ["480ec5108f3adf7b"] = { "Cosa gli è successo, all'inizio? Quando l'ho... incontrato, era piuttosto malvagio.", "." },
  ["4826bb7abb366479"] = { "⟦Glacial Cloak=Mantello Glaciale⟧.", "." },
  ["48273304fadb2448"] = { "Che posso fare per te?", "." },
  ["48273510fadba3cc"] = { "Che posso fare per te?", "." },
  ["4828c4258cd592eb"] = { "La vista non l'avrò, ma la visione sì.\n\nTratto soprattutto con cacciatori e ladri, {race}.", "." },
  ["482b013ca7d6fa39"] = { "Non mi farò attirare via!", "." },
  ["482c1ad36a3016d5"] = { "Le nostre forze sono pronte alla battaglia e smaniose di versare il sangue dell'⟦Alliance=Alleanza⟧. Presto il nostro capitano entrerà nel ⟦Iceblood Garrison=Presidio di Brinarossa⟧ e la guerra ricomincerà!", "." },
  ["482ed74f5bf0d32e"] = { "Portami nel ⟦Molten Core=Nucleo Ardente⟧, Lothos.", "." },
  ["482f9835976dab38"] = { "%s si prepara a pungere la sua vittima, in un ultimo gesto disperato!", "." },
  ["4831641bff523a32"] = { "Niby, sei un idiota.", "." },
  ["4831e05b60f220de"] = { "Salute, Antico. Ho fatto tutto ciò che mi è stato chiesto. Ora ti chiedo di concedermi Lok'delar.", "." },
  ["484682169ba0bfa8"] = { "Resta per il prossimo spettacolo di fuochi d'artificio! A partire dalle sei di sera, ce n'è uno ogni ora allo scoccare dell'ora!", "." },
  ["4847c75ccf98be50"] = { "Vi taglieremo la gola e vi dissangueremo!", "." },
  ["4848fcdd0e3ee432"] = { "Non fai che rimandare l'inevitabile!", "." },
  ["484aeb76d5243f49"] = { "Se sento un solo commento sugli uccelli acquatici, ti nutrirai con un tubicino.", "." },
  ["484c1a81dfbbe759"] = { "Dov'è l'anziano Cigliatonanti?", "." },
  ["484fe496de526f75"] = { "{name}, sei riuscit<o/a> a raccogliere qualche informazione? Hai trovato il messaggero?", "." },
  ["485b1f1faa992e08"] = { "Possiamo sconfiggere queste creature immonde!", "." },
  ["485cfdfcca7dbd34"] = { "Bene, ragazzi, la pausa pranzo è finita. Torniamo al lavoro. Se il resto della giornata va bene come stamattina, magari stacchiamo prima.", "." },
  ["485cff7a35f578cb"] = { "Perché cucinare, quando tutto ha il sapore della cenere in bocca? Sempre che tu ce l'abbia ancora, una bocca. E va bene, vai a ⟦Undercity=Sepulcra⟧, a sud di Brill, e chiedi a un ⟦Undercity Guardian=Guardiano di Sepulcra⟧ come raggiungere il loro istruttore di cucina. Per arrivarci puoi prendere gli ascensori che scendono dal retro delle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧.", "." },
  ["485fb40be5901451"] = { "Padrone, la tua saggezza è pari solo alla tua stazza!", "." },
  ["4860e91472de152d"] = { "|cffffff00La Torre della Corona è stata conquistata dall'⟦Horde=Orda⟧!|r", "." },
  ["48612b7d4a8dc9ed"] = { "Non hai ancora l'abilità per studiare con me. Va' a parlare con il dottor Martin Felben laggiù, oppure sali la rampa a sud-est e cerca il dottor Marsh. Sono Reietti che possono darti l'addestramento che ti serve.", "." },
  ["48656d2be077ef2d"] = { "Ci vuole ben più di un cadavere in putrefazione per fermarci!", "." },
  ["4867d11f53242a87"] = { "Ehi, Jangdor, puoi insegnarmi di nuovo a fare le ⟦Wild Leather Leggings=Gambiere di Cuoio Selvatico⟧?", "." },
  ["48690a2dad45c6a3"] = { "Servi bene la Luce, {class}.", "." },
  ["48765f9811d422d6"] = { "Va bene, mettilo giù là e me ne occupo io.", "." },
  ["4877af5087bb81fb"] = { "Oh, quanti drammi e quante storie ha fatto il giovane padrone. Si sarebbe detto che il destino del mondo poggiasse tutto sulle sue spalle. Solo i mortali potrebbero avere una visione così distorta del nostro mondo.\n\nAhimè, mi ha lasciato i suoi miseri segreti magici... Compendi o qualche sciocchezza del genere. Non so che farmene di queste magie da poco, ma forse a te potrebbero interessare i loro incantamenti.", "." },
  ["4887e75bd19fef0a"] = { "Conosco una druida che vive in cima alla collina sopra la ⟦Wailing Caverns=Caverna dei Lamenti⟧, {name}. Forse potrà dirti di più su questa scheggia che hai trovato.", "." },
  ["48956a7608725614"] = { "Noi pensa che tu serve aiuto.", "." },
  ["489a2ee9eac24910"] = { "I seguaci delle antiche vie degli ⟦Highborne=Alti Nobili⟧ non sono mai stati così affamati di conoscenza e desiderosi di riprendersi ciò che abbiamo perduto. Se cerchi di brandire il potere arcano e ne hai l'attitudine, posso aiutarti a muovere i prossimi passi.", "." },
  ["489f16c76395a922"] = { "%s si volta verso sud-est e guaisce, prima di tornare a guardarti.", "." },
  ["48a45d344014d505"] = { "<Jim'bek ti fissa negli occhi mentre tira una lunga boccata dal narghilè.>\n\nSalve, amico. Ti serve un tappeto? Una coperta? O solo un po' di stoffa per il tuo prossimo lavoro? Ci penso io.", "." },
  ["48a4897d8da2b215"] = { "Per grazia di Elune, è un piacere per me offrirti il destriero più pregiato di tutta Teldrassil, e forse del mondo: la fiera della notte. Da anni l'Esercito delle Sentinelle fa affidamento sul valore di questi compagni.\n\nPrenditi il tuo tempo, <amico/amica>, ed esamina ciascuna come preferisci. Di certo non resterai <deluso/delusa>.", "." },
  ["48b0afe3901295dd"] = { "Ho una bella scelta di pozioni e pergamene esotiche. Ma non sono per i deboli di cuore!", "." },
  ["48bc5ae3804d85b9"] = { "Salve, salve! <Benvenuto/Benvenuta> nella mia cucina, <signore/signora>! È qui che nascono tutte le migliori prelibatezze della Scarlet Raven Tavern. Ah, senti che profumo meraviglioso!", "." },
  ["48bdd7004e8ab847"] = { "Valstann Staghelm era il braccio destro di Fandral. Un guerriero fiero e nobile, dalla dedizione e dall'adorazione incrollabili verso il padre... e gli Imperatori Gemelli vi scorsero una debolezza. Una debolezza da sfruttare.", "." },
  ["48c36b1043a8b213"] = { "Stolti... Uccidete quello con la veste!", "." },
  ["48c6365f6409bf81"] = { "Grazie, <ragazzo/ragazza>. Grazie infinite.", "." },
  ["48c8e9b0beb79812"] = { "Perché sta succedendo? In poche parole, gli spiriti del vento sono semplicemente... svaniti. Un giorno c'erano, e il giorno dopo non c'erano più. Non so descrivere bene ciò che abbiamo provato noi plasmavento quando è successo. È stato come se un grande silenzio fosse calato su tutti noi e poi... un vuoto profondo.\n\nI miseri spettri che probabilmente hai incontrato là fuori sono solo ombre della gloria dei veri spiriti del vento. Privi di coscienza, senza meta, ben lontani dagli spiriti benevoli accanto ai quali abbiamo vissuto in armonia per migliaia di anni.", "." },
  ["48c913bcdda90735"] = { "Chi è l'eroe più amato del regno, chiedi? Ecco la classifica attuale!\n\nThrall: $2200w\n\nCairne: $2201w\n\nSylvanas: $2202w\n\nTotale ⟦Horde=Orda⟧: $2207w\n\nBolvar: $2203w\n\nMagni: $2204w\n\nTyrande: $2205w\n\nTotale ⟦Alliance=Alleanza⟧: $2206w\n\nSe vuoi dare il tuo voto, ricordati di consegnare le tue raccolte di doni!", "." },
  ["48c940835605c8c2"] = { "Falgran Hastil a rapporto, signore. Scoprirò dove portano le impronte di zoccoli e tornerò a riferire.", "." },
  ["48ca3866ec7ef733"] = { "Stupidità! Intorno a me solo stupidità!", "." },
  ["48d0cdabf342ed62"] = { "Portami con te, <signore/signora>.", "." },
  ["48da80090a6d7b6c"] = { "Myolor, un tempo ero Fabbro d'Armi e ora vorrei imparare invece la via del fabbro di armature. Mi insegnerai?", "." },
  ["48e5e291893b037a"] = { "L'Occhio vede tutto ciò che sta entro la sua sfera d'influenza, {class}. Che cosa desideri vedere?", "." },
  ["48ebc4b8a8d2df84"] = { "Salute, {class}. Ti servono armi?\n\nMi ha addestrato Antarion di Ban'aethal, con segreti tramandati dagli antichi maestri magifabbri di Kalimdor.\n\nSull'⟦Zephras Isle=Isola di Zephras⟧ non troverai armi migliori delle mie.", "." },
  ["48ec0275b839214f"] = { "La tua sicurezza è ben fondata, <viaggiatore/viaggiatrice>. Ora la tua vera istruzione può avere inizio!", "." },
  ["48f633907788b022"] = { "Tutto tranquillo a ⟦Sentinel Hill=Guardiacolle⟧, lord Stoutmantle. Però a ⟦Moonbrook=Rivoluna⟧ segnalano grandi movimenti dei Defias.", "." },
  ["48fb7d1cdb189410"] = { "Ora possiamo ricostruire! Per l'⟦Horde=Orda⟧!", "." },
})
